export const OBSERVER_ROOT_MARGIN = "0px 0px -70% 0px";
export const ACTIVE_HEADING_TOP_OFFSET = 8;

export const DEFAULT_SCROLL_TOP_OFFSET = 24;

"use client";

import type { ReactNode } from "react";
import type { EditorProps } from "../../core/types";
import { Editor } from "../../editor";
import { EditorTableOfContents } from "./sidebar";

interface EditorWithTocProps extends EditorProps {
  /** Replace the default TOC sidebar with a custom element. */
  toc?: ReactNode;
  /** Additional className for the TOC sidebar. */
  tocClassName?: string;
}

/**
 * A composition wrapper that renders the `Editor` alongside a sticky
 * Table of Contents sidebar.
 *
 * The TOC is rendered **inside** the LexicalComposer tree (via `slots.shell`)
 * so it can read heading state from the editor. The consumer controls the
 * outer page layout — this component only provides the two-column structure.
 */
export function EditorWithToc({
  slots,
  toc,
  tocClassName,
  ...props
}: EditorWithTocProps) {
  return (
    <Editor
      {...props}
      slots={{
        ...slots,
        shell: ({ children }) => (
          <>
            <div className="min-w-0">{children}</div>
            {toc !== null && (
              <div className="pointer-events-none fixed top-24 right-6 z-30 hidden xl:block">
                <div className="pointer-events-auto">
                  {toc ?? <EditorTableOfContents className={tocClassName} />}
                </div>
              </div>
            )}
          </>
        ),
      }}
    />
  );
}

"use client";

import type { ExtraEditorFeature } from "../../core/types";
import { EditorTableOfContents } from "./sidebar";

/**
 * Default TOC placement: a fixed sidebar on the right edge of the viewport.
 * Consumers who need custom placement can render `EditorTableOfContents`
 * themselves inside any editor slot instead of using this descriptor (see
 * `EditorWithToc` for a slots-based composition).
 */
export function TocFeaturePlugin() {
  return (
    <div className="pointer-events-none fixed top-24 right-6 z-30 hidden xl:block">
      <div className="pointer-events-auto">
        <EditorTableOfContents />
      </div>
    </div>
  );
}

/**
 * Installs the table-of-contents sidebar. Ships as the `editor-toc` registry
 * item.
 */
export const tocFeature: ExtraEditorFeature = {
  id: "toc",
  plugin: TocFeaturePlugin,
};

"use client";

import type { TableOfContentsEntry } from "@lexical/react/LexicalTableOfContentsPlugin";
import { mergeRegister } from "@lexical/utils";
import { $getNodeByKey, type LexicalEditor, type NodeKey } from "lexical";
import { useEffect, useEffectEvent, useReducer, useRef } from "react";
import { OBSERVER_ROOT_MARGIN } from "./constants";
import type { TocState } from "./types";
import {
  getScrollParent,
  resolveActiveHeadingKey,
  resolveSelectedHeadingKey,
  scrollToHeading,
} from "./utils";

type TocAction =
  | { type: "set_active"; payload: NodeKey | null }
  | { type: "set_selected"; payload: NodeKey | null };

const tocReducer = (state: TocState, action: TocAction): TocState => {
  switch (action.type) {
    case "set_active":
      return state.activeKey === action.payload
        ? state
        : { ...state, activeKey: action.payload };
    case "set_selected":
      return state.selectedHeadingKey === action.payload
        ? state
        : { ...state, selectedHeadingKey: action.payload };
    default:
      return state;
  }
};

export function useActiveHeading(
  entries: readonly TableOfContentsEntry[],
  editor: LexicalEditor
): {
  activeKey: NodeKey | null;
  selectedKey: NodeKey | null;
  handleHeadingClick: (key: NodeKey) => void;
} {
  const [state, dispatch] = useReducer(tocReducer, {
    activeKey: null,
    selectedHeadingKey: null,
  });

  // Keep a ref to the latest state so callbacks can read it without dependencies
  const stateRef = useRef(state);
  useEffect(() => {
    stateRef.current = state;
  }, [state]);

  const rafRef = useRef<number>(0);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // References to keep callbacks stable
  const entriesRef = useRef(entries);
  useEffect(() => {
    entriesRef.current = entries;
  }, [entries]);

  // Track scroll direction and position
  const prevScrollTop = useRef(0);
  const scrollDirection = useRef<"up" | "down">("down");
  const isProgrammaticScrolling = useRef(false);

  // Cache scroll parent and header offset
  const scrollParentRef = useRef<HTMLElement | Window>(window);
  const stickyHeadersRef = useRef<HTMLElement[]>([]);
  const cachedOffset = useRef(24);

  // Resolve scroll parent of editor
  const updateScrollParent = () => {
    const rootEl = editor.getRootElement();
    scrollParentRef.current = rootEl ? getScrollParent(rootEl) : window;
  };

  // Find fixed/sticky headers once and cache them
  const updateStickyHeaders = () => {
    const headers = Array.from(document.querySelectorAll("header"));
    const sticky: HTMLElement[] = [];
    for (const header of headers) {
      if (header instanceof HTMLElement) {
        const { position } = window.getComputedStyle(header);
        if (position === "fixed" || position === "sticky") {
          sticky.push(header);
        }
      }
    }
    stickyHeadersRef.current = sticky;
  };

  // Compute the current scroll top offset dynamically but extremely fast
  const updateCachedOffset = () => {
    let maxHeaderBottom = 0;
    for (const header of stickyHeadersRef.current) {
      maxHeaderBottom = Math.max(
        maxHeaderBottom,
        header.getBoundingClientRect().bottom
      );
    }
    cachedOffset.current = Math.max(24, Math.round(maxHeaderBottom + 16));
  };

  // Update layout info on resize
  const handleResize = useEffectEvent(() => {
    updateScrollParent();
    updateStickyHeaders();
    updateCachedOffset();
  });

  // Sync active heading logic
  const syncActiveHeading = useEffectEvent(() => {
    if (isProgrammaticScrolling.current) {
      return;
    }

    cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(() => {
      // Determine scroll direction
      const scrollParent = scrollParentRef.current;
      const isWindow = scrollParent === window;
      const scrollTop = isWindow
        ? window.scrollY
        : (scrollParent as HTMLElement).scrollTop;

      if (scrollTop > prevScrollTop.current) {
        scrollDirection.current = "down";
      } else if (scrollTop < prevScrollTop.current) {
        scrollDirection.current = "up";
      }
      prevScrollTop.current = scrollTop;

      // Update cached offset dynamically from sticky headers
      updateCachedOffset();

      dispatch({
        type: "set_active",
        payload: resolveActiveHeadingKey(entriesRef.current, editor, {
          currentActiveKey: stateRef.current.activeKey,
          scrollDirection: scrollDirection.current,
          scrollParent,
          offset: cachedOffset.current,
        }),
      });
    });
  });

  // Handle selected heading (cursor selection)
  useEffect(() => {
    return mergeRegister(
      editor.registerUpdateListener(({ editorState }) => {
        editorState.read(() => {
          dispatch({
            type: "set_selected",
            payload: resolveSelectedHeadingKey(),
          });
        });
      })
    );
  }, [editor]);

  // Listen to keys of entries. Re-setup observers only when the keys list changes.
  const keysStr = entries.map(([key]) => key).join(",");
  const prevKeysStrRef = useRef("");

  useEffect(() => {
    // Initial setups
    handleResize();

    // Rebuild observer only when the list of heading keys changes
    const keysChanged = keysStr !== prevKeysStrRef.current;
    prevKeysStrRef.current = keysStr;

    let observer: IntersectionObserver | null = null;

    if (keysChanged) {
      observer = new IntersectionObserver(syncActiveHeading, {
        rootMargin: OBSERVER_ROOT_MARGIN,
        threshold: 0,
      });

      for (const [key] of entriesRef.current) {
        const element = editor.getElementByKey(key);
        if (element instanceof HTMLElement) {
          observer.observe(element);
        }
      }
    }

    // Always sync active heading when keys change or on mount
    syncActiveHeading();

    // Listen on window for scroll with capture: true to catch all scroll events
    window.addEventListener("scroll", syncActiveHeading, {
      capture: true,
      passive: true,
    });
    window.addEventListener("resize", handleResize, { passive: true });

    return () => {
      cancelAnimationFrame(rafRef.current);
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      observer?.disconnect();
      window.removeEventListener("scroll", syncActiveHeading, {
        capture: true,
      });
      window.removeEventListener("resize", handleResize);
    };
  }, [keysStr, editor]);

  // Scroll to heading click handler
  const handleHeadingClick = (key: NodeKey) => {
    const headingElement = editor.getElementByKey(key);
    if (!(headingElement instanceof HTMLElement)) {
      return;
    }

    // Stop any pending animation frames
    cancelAnimationFrame(rafRef.current);

    // Instantly update active heading highlight in the UI for premium UX
    isProgrammaticScrolling.current = true;
    dispatch({ type: "set_active", payload: key });
    dispatch({ type: "set_selected", payload: key });

    // Focus editor and place cursor
    editor.update(
      () => {
        $getNodeByKey(key)?.selectStart();
      },
      { discrete: true }
    );
    editor.getRootElement()?.focus({ preventScroll: true });

    // Recalculate layout targets
    updateScrollParent();
    updateStickyHeaders();
    updateCachedOffset();

    const scrollParent = scrollParentRef.current;
    const offset = cachedOffset.current;

    const onScrollEnd = () => {
      isProgrammaticScrolling.current = false;
      cleanup();
    };

    const handleUserInterrupt = () => {
      isProgrammaticScrolling.current = false;
      cleanup();
    };

    const cleanup = () => {
      scrollParent.removeEventListener("scrollend", onScrollEnd);
      window.removeEventListener("wheel", handleUserInterrupt);
      window.removeEventListener("touchmove", handleUserInterrupt);
      window.removeEventListener("keydown", handleUserInterrupt);
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };

    // Listen for scrollend or user interruption to restore scroll tracking
    scrollParent.addEventListener("scrollend", onScrollEnd, { once: true });
    window.addEventListener("wheel", handleUserInterrupt, { passive: true });
    window.addEventListener("touchmove", handleUserInterrupt, {
      passive: true,
    });
    window.addEventListener("keydown", handleUserInterrupt, {
      passive: true,
    });

    // Safety timeout in case scrollend doesn't trigger
    timeoutRef.current = setTimeout(() => {
      if (isProgrammaticScrolling.current) {
        onScrollEnd();
      }
    }, 800);

    // Perform smooth scroll
    scrollToHeading(headingElement, offset);
  };

  return {
    activeKey: state.activeKey,
    selectedKey: state.selectedHeadingKey,
    handleHeadingClick,
  };
}

"use client";

import {
  TableOfContentsPlugin as LexicalTableOfContentsPlugin,
  type TableOfContentsEntry,
} from "@lexical/react/LexicalTableOfContentsPlugin";
import type { LexicalEditor } from "lexical";
import type { ReactNode } from "react";

interface EditorTableOfContentsPluginProps {
  children: (
    entries: readonly TableOfContentsEntry[],
    editor: LexicalEditor
  ) => ReactNode;
}

export function EditorTableOfContentsPlugin({
  children,
}: EditorTableOfContentsPluginProps) {
  return (
    <LexicalTableOfContentsPlugin>
      {(entries, editor) => <>{children(entries, editor)}</>}
    </LexicalTableOfContentsPlugin>
  );
}

"use client";

import type { TableOfContentsEntry } from "@lexical/react/LexicalTableOfContentsPlugin";
import type { LexicalEditor, NodeKey } from "lexical";
import { AlignLeftIcon } from "lucide-react";
import { useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { useActiveHeading } from "./hooks";
import { EditorTableOfContentsPlugin } from "./plugin";

const DASH_WIDTHS: Record<string, string> = {
  h1: "w-6",
  h2: "w-4.5",
  h3: "w-3.5",
  h4: "w-2.5",
  h5: "w-2",
  h6: "w-1.5",
};

const INDENT_CLASSES: Record<string, string> = {
  h1: "pl-1",
  h2: "pl-4",
  h3: "pl-7",
  h4: "pl-10",
  h5: "pl-12",
  h6: "pl-14",
};

function EditorTocMiniBars({
  activeKey,
  entries,
  onHeadingClick,
}: {
  activeKey: NodeKey | null;
  entries: readonly TableOfContentsEntry[];
  onHeadingClick: (key: NodeKey) => void;
}) {
  if (entries.length === 0) {
    return (
      <div className="flex flex-col items-end gap-2 py-2 opacity-40">
        <span className="h-[2.5px] w-6 rounded-full bg-muted-foreground/40" />
        <span className="h-[2.5px] w-4 rounded-full bg-muted-foreground/40" />
        <span className="h-[2.5px] w-3 rounded-full bg-muted-foreground/40" />
      </div>
    );
  }

  return (
    // Capped so heading-heavy documents don't stretch the mini-bars to full
    // editor height; overflow scrolls with a thin scrollbar.
    <div className="scrollbar-thin scrollbar-thumb-muted scrollbar-track-transparent flex max-h-[70vh] flex-col items-end gap-2 overflow-y-auto py-2">
      {entries.map(([key, text, tag]) => {
        const isActive = key === activeKey;
        const widthClass = DASH_WIDTHS[tag] ?? "w-3.5";

        return (
          <button
            aria-label={`Jump to ${text.trim() || "heading"}`}
            className="group relative flex cursor-pointer items-center justify-end py-0.5 outline-none transition-all duration-150"
            key={key}
            onClick={() => onHeadingClick(key)}
            type="button"
          >
            <span
              className={cn(
                "h-[2.5px] rounded-full transition-all duration-200 ease-out",
                widthClass,
                isActive
                  ? "scale-x-110 bg-primary shadow-xs"
                  : "bg-muted-foreground/30 group-hover:bg-muted-foreground/60"
              )}
            />
          </button>
        );
      })}
    </div>
  );
}

function EditorTocPopoverCard({
  activeKey,
  entries,
  onHeadingClick,
}: {
  activeKey: NodeKey | null;
  entries: readonly TableOfContentsEntry[];
  onHeadingClick: (key: NodeKey) => void;
}) {
  if (entries.length === 0) {
    return (
      <div className="fade-in-0 zoom-in-95 absolute top-0 right-0 z-50 flex min-w-[200px] animate-in flex-col items-center justify-center gap-2 rounded-2xl border border-border/50 bg-popover/95 px-5 py-6 text-center shadow-2xl backdrop-blur-md duration-150">
        <div className="flex size-7 items-center justify-center rounded-lg bg-muted/20 text-muted-foreground/60">
          <AlignLeftIcon className="size-3.5" />
        </div>
        <p className="font-medium text-muted-foreground text-xs">
          No outline available
        </p>
      </div>
    );
  }

  return (
    <nav
      aria-label="Table of contents popover"
      className="fade-in-0 zoom-in-95 scrollbar-thin scrollbar-thumb-muted scrollbar-track-transparent relative top-0 right-0 z-50 max-h-[70vh] min-w-[240px] max-w-[320px] animate-in overflow-y-auto rounded-2xl border border-border/50 bg-popover/95 p-3 shadow-2xl backdrop-blur-md duration-150"
    >
      <ul className="flex flex-col gap-0.5">
        {entries.map(([key, text, tag]) => {
          const headingText = text.trim() || "Untitled";
          const isActive = key === activeKey;
          const indentClass = INDENT_CLASSES[tag] ?? "pl-1";

          return (
            <li className="list-none" key={key}>
              <button
                aria-current={isActive ? "location" : undefined}
                className={cn(
                  "relative flex w-full cursor-pointer select-none items-center gap-2 rounded-lg px-2.5 py-1.5 text-left text-xs outline-none transition-colors duration-150",
                  indentClass,
                  isActive
                    ? "bg-primary/10 font-medium text-primary"
                    : "text-muted-foreground hover:bg-accent/80 hover:text-foreground"
                )}
                onClick={() => onHeadingClick(key)}
                type="button"
              >
                <span className="truncate">{headingText}</span>
              </button>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

function EditorTableOfContentsInner({
  className,
  editor,
  entries,
}: {
  className?: string;
  editor: LexicalEditor;
  entries: readonly TableOfContentsEntry[];
}) {
  const { activeKey, handleHeadingClick } = useActiveHeading(entries, editor);
  const [isHovered, setIsHovered] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleMouseEnter = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setIsHovered(true);
  };

  const handleMouseLeave = () => {
    timeoutRef.current = setTimeout(() => {
      setIsHovered(false);
    }, 150);
  };

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: hover popover container
    <aside
      aria-label="Table of contents outline"
      className={cn(
        "group relative flex select-none flex-col items-end",
        className
      )}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {isHovered ? (
        <EditorTocPopoverCard
          activeKey={activeKey}
          entries={entries}
          onHeadingClick={handleHeadingClick}
        />
      ) : (
        <EditorTocMiniBars
          activeKey={activeKey}
          entries={entries}
          onHeadingClick={handleHeadingClick}
        />
      )}
    </aside>
  );
}

export function EditorTableOfContents({ className }: { className?: string }) {
  return (
    <EditorTableOfContentsPlugin>
      {(entries, editor) => (
        <EditorTableOfContentsInner
          className={className}
          editor={editor}
          entries={entries}
        />
      )}
    </EditorTableOfContentsPlugin>
  );
}

import type { NodeKey } from "lexical";

export type TocHeadingTag = "h1" | "h2" | "h3" | "h4" | "h5" | "h6";

export interface TocState {
  activeKey: NodeKey | null;
  selectedHeadingKey: NodeKey | null;
}

import type { TableOfContentsEntry } from "@lexical/react/LexicalTableOfContentsPlugin";
import { $isHeadingNode } from "@lexical/rich-text";
import {
  $getSelection,
  $isRangeSelection,
  type LexicalEditor,
  type NodeKey,
} from "lexical";
import {
  ACTIVE_HEADING_TOP_OFFSET,
  DEFAULT_SCROLL_TOP_OFFSET,
} from "./constants";

export const getScrollParent = (
  element: HTMLElement | null
): HTMLElement | Window => {
  let parent = element;
  while (parent) {
    if (parent === document.body || parent === document.documentElement) {
      break;
    }
    const style = window.getComputedStyle(parent);
    if (
      (style.overflowY === "auto" || style.overflowY === "scroll") &&
      parent.scrollHeight > parent.clientHeight
    ) {
      return parent;
    }
    parent = parent.parentElement;
  }
  return window;
};

export const getScrollTopOffset = () => {
  const headers = Array.from(document.querySelectorAll("header"));
  let maxHeaderBottom = 0;

  for (const header of headers) {
    if (!(header instanceof HTMLElement)) {
      continue;
    }

    const { position } = window.getComputedStyle(header);
    if (position !== "fixed" && position !== "sticky") {
      continue;
    }

    maxHeaderBottom = Math.max(
      maxHeaderBottom,
      header.getBoundingClientRect().bottom
    );
  }

  return Math.max(DEFAULT_SCROLL_TOP_OFFSET, Math.round(maxHeaderBottom + 16));
};

export const scrollToHeading = (
  headingElement: HTMLElement,
  offset?: number
) => {
  const scrollParent = getScrollParent(headingElement);
  const resolvedOffset = offset ?? getScrollTopOffset();

  if (scrollParent === window) {
    const top =
      window.scrollY +
      headingElement.getBoundingClientRect().top -
      resolvedOffset;
    window.scrollTo({
      behavior: "smooth",
      top: Math.max(0, top),
    });
  } else {
    const parentEl = scrollParent as HTMLElement;
    const parentRect = parentEl.getBoundingClientRect();
    const headingRect = headingElement.getBoundingClientRect();
    const top =
      parentEl.scrollTop + (headingRect.top - parentRect.top) - resolvedOffset;
    parentEl.scrollTo({
      behavior: "smooth",
      top: Math.max(0, top),
    });
  }
};

const isAtAbsoluteBottom = (scrollParent: HTMLElement | Window): boolean => {
  const isWindow = scrollParent === window;
  const scrollTop = isWindow
    ? window.scrollY
    : (scrollParent as HTMLElement).scrollTop;
  const scrollHeight = isWindow
    ? document.documentElement.scrollHeight
    : (scrollParent as HTMLElement).scrollHeight;
  const clientHeight = isWindow
    ? window.innerHeight
    : (scrollParent as HTMLElement).clientHeight;

  const maxScroll = scrollHeight - clientHeight;
  return maxScroll > 0 && maxScroll - scrollTop <= 40;
};

const getTargetLine = (
  scrollParent: HTMLElement | Window,
  offset: number
): number => {
  if (scrollParent === window) {
    return offset;
  }
  const parentRect = (scrollParent as HTMLElement).getBoundingClientRect();
  return parentRect.top + offset;
};

const findHighestActiveHeadingKey = (
  entries: readonly TableOfContentsEntry[],
  editor: LexicalEditor,
  targetLine: number,
  currentActiveKey: NodeKey | null,
  scrollDirection: "up" | "down"
): NodeKey | null => {
  let activeKey: NodeKey | null = null;
  const hysteresisBuffer = 20;

  for (const [key] of entries) {
    const element = editor.getElementByKey(key);
    if (!(element instanceof HTMLElement && element.isConnected)) {
      continue;
    }

    const isCurrentlyActive = currentActiveKey === key;
    const threshold =
      isCurrentlyActive && scrollDirection === "up"
        ? targetLine + hysteresisBuffer
        : targetLine;

    if (element.getBoundingClientRect().top <= threshold) {
      activeKey = key;
      continue;
    }

    break;
  }

  return activeKey;
};

const resolveAbsoluteBottomHeadingKey = (
  entries: readonly TableOfContentsEntry[],
  editor: LexicalEditor,
  scrollParent: HTMLElement | Window
): NodeKey | null => {
  if (!isAtAbsoluteBottom(scrollParent)) {
    return null;
  }

  const lastKey = entries.at(-1)?.[0];
  if (!lastKey) {
    return null;
  }

  const lastElement = editor.getElementByKey(lastKey);
  if (!(lastElement instanceof HTMLElement)) {
    return null;
  }

  const clientHeight =
    scrollParent === window
      ? window.innerHeight
      : (scrollParent as HTMLElement).clientHeight;

  if (lastElement.getBoundingClientRect().top <= clientHeight) {
    return lastKey;
  }

  return null;
};

export const resolveActiveHeadingKey = (
  entries: readonly TableOfContentsEntry[],
  editor: LexicalEditor,
  options?: {
    currentActiveKey?: NodeKey | null;
    scrollDirection?: "up" | "down";
    scrollParent?: HTMLElement | Window;
    offset?: number;
  }
): NodeKey | null => {
  if (entries.length === 0) {
    return null;
  }

  const scrollParent = options?.scrollParent ?? window;
  const offset = options?.offset ?? getScrollTopOffset();
  const currentActiveKey = options?.currentActiveKey ?? null;
  const scrollDirection = options?.scrollDirection ?? "down";
  const targetLine = getTargetLine(
    scrollParent,
    offset + ACTIVE_HEADING_TOP_OFFSET
  );

  const activeKey = findHighestActiveHeadingKey(
    entries,
    editor,
    targetLine,
    currentActiveKey,
    scrollDirection
  );

  const bottomKey = resolveAbsoluteBottomHeadingKey(
    entries,
    editor,
    scrollParent
  );

  return bottomKey ?? activeKey ?? entries[0]?.[0] ?? null;
};

export const resolveSelectedHeadingKey = (): NodeKey | null => {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) {
    return null;
  }

  const topLevelElement = selection.anchor
    .getNode()
    .getTopLevelElementOrThrow();
  if (!$isHeadingNode(topLevelElement)) {
    return null;
  }

  return topLevelElement.getKey();
};
